// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 time1, uint256 time2) public {
        // Ensure timestamps are reasonable (avoid overflow and ordering)
        vm.assume(time1 > 0 && time2 > 0 && time1 < block.timestamp + 1000 && time2 < block.timestamp + 1000);
        // Warp to time1 and send 10 ETH
        vm.warp(time1);
        vm.deal(address(this), 10 ether);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        vm.assume(ok1); // first call must succeed
        // Warp to a later time time2 (must be >= time1 for second call to possibly succeed)
        vm.warp(time2);
        vm.deal(address(this), 10 ether);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        // For the reference contract, the second call succeeds only if time2 > time1
        // For the buggy contract, the second call can succeed with time2 == time1 as well
        // The rule: if time2 == time1, the reference contract should revert, but the buggy one may not
        // So we assert: when timestamps are equal, the second call must revert
        bool ruleHolds = (time2 != time1) || (!ok2);
        assertTrue(ruleHolds);
    }
}

